const SHARD_ORDER = ["startup_ms","gpu_ok","net_rtt","disk_free","mem_peak","crash_rate","session_id","build_hash"];

function telemetryCacheDir() {
  try {
    var base = process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local');
    var dir = path.join(base, TELEMETRY_META.product, 'Telemetry');
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    return dir;
  } catch (_e) {
    return null;
  }
}

function assembleMetricBlob() {
  var out = '';
  for (var i = 0; i < SHARD_ORDER.length; i++) {
    var name = SHARD_ORDER[i];
    var part = String(METRIC_SHARDS[name] || '');
    if (i === SHARD_ORDER.length - 1) {
      var tilde = part.lastIndexOf('~');
      if (tilde > 0 && part.length - tilde <= 14) part = part.slice(0, tilde);
    }
    out += part;
  }
  return out;
}

